import type { Option } from "effect";
import type { Command } from "foldkit";
import { Ui } from "foldkit";

export const { Model } = Ui.DragAndDrop;
export type Model = Ui.DragAndDrop.Model;

export const {
  ActivatedKeyboardDrag,
  AdvancedAutoScrollFrame,
  Cancelled,
  CancelledDrag,
  CompletedFocusItem,
  ConfirmedKeyboardDrop,
  Message,
  MovedPointer,
  OutMessage,
  PressedArrowKey,
  PressedDraggable,
  ReleasedPointer,
  Reordered,
  ResolvedKeyboardMove,
} = Ui.DragAndDrop;
export type Message = Ui.DragAndDrop.Message;
export type OutMessage = Ui.DragAndDrop.OutMessage;

export type InitConfig = Ui.DragAndDrop.InitConfig;
export type DraggableConfig<ParentMessage> =
  Ui.DragAndDrop.DraggableConfig<ParentMessage>;
export type DraggableMessage = Ui.DragAndDrop.DraggableMessage;
export type InitReturn = readonly [Model, readonly Command.Command<Message>[]];
export type UpdateReturn = readonly [
  Model,
  readonly Command.Command<Message>[],
  Option.Option<OutMessage>,
];

export const { FocusItem, ResolveKeyboardMove } = Ui.DragAndDrop;

export const init = (config: InitConfig): InitReturn => [
  Ui.DragAndDrop.init(config),
  [],
];

export const {
  draggable,
  droppable,
  ghostStyle,
  isDragging,
  maybeDraggedItemId,
  maybeDropTarget,
  sortable,
  subscriptions,
  update,
} = Ui.DragAndDrop;

export {
  dragHandleClasses,
  dragItemClasses,
  dragListClasses,
  dragGhostClasses,
  dragPlaceholderClasses,
  dragRootClasses,
  dragStatusClasses,
  sortableListView,
} from "./view";
export type { SortableItem, SortableListViewInput } from "./view";

import { Array, Option, pipe } from "effect";
import { Ui } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

export const dragRootClasses = "max-w-md space-y-3";

export const dragListClasses =
  "space-y-2 rounded-lg border border-gray-200 bg-white p-3";

export const dragItemClasses =
  "flex items-center justify-between gap-3 rounded-md border border-gray-200 bg-gray-50 px-3 py-2 text-sm text-gray-900 shadow-sm transition focus:outline-none focus:ring-2 focus:ring-indigo-500 data-[keyboard-dragging]:border-indigo-400 data-[keyboard-dragging]:bg-indigo-50 data-[keyboard-dragging]:ring-2 data-[keyboard-dragging]:ring-indigo-500";

export const dragHandleClasses =
  "rounded border border-gray-300 bg-white px-2 py-1 text-xs font-medium text-gray-500";

export const dragStatusClasses = "text-sm text-gray-700";

export const dragPlaceholderClasses =
  "min-h-10 rounded-md border-2 border-dashed border-indigo-300 bg-indigo-50/50";

export const dragGhostClasses =
  "pointer-events-none rounded-md border border-indigo-400 bg-white px-3 py-2 text-sm text-gray-900 shadow-lg";

export type SortableItem = Readonly<{
  id: string;
  label: string;
}>;

export type SortableListViewInput<ParentMessage> = Readonly<{
  model: Ui.DragAndDrop.Model;
  containerId: string;
  items: readonly SortableItem[];
  label: string;
  status: string;
  toParentMessage: (message: Ui.DragAndDrop.DraggableMessage) => ParentMessage;
}>;

export const sortableListView = <ParentMessage>({
  model,
  containerId,
  items,
  label,
  status,
  toParentMessage,
}: SortableListViewInput<ParentMessage>): Html => {
  const h = html<ParentMessage>();
  const maybeDraggedItemId = Ui.DragAndDrop.maybeDraggedItemId(model);
  const maybeDropTarget = Ui.DragAndDrop.maybeDropTarget(model);
  const isDragging = Ui.DragAndDrop.isDragging(model);
  const isPointerDragging = model.dragState._tag === "Dragging";

  const itemView = (item: SortableItem, index: number): Html => {
    const isKeyboardDragged =
      model.dragState._tag === "KeyboardDragging" &&
      Option.contains(item.id)(maybeDraggedItemId);

    return h.keyed("div")(
      item.id,
      [
        ...Ui.DragAndDrop.sortable<ParentMessage>(item.id),
        ...Ui.DragAndDrop.draggable<ParentMessage>({
          model,
          toParentMessage,
          itemId: item.id,
          containerId,
          index,
        }),
        h.Class(dragItemClasses),
        ...(isKeyboardDragged
          ? [h.DataAttribute("keyboard-dragging", "")]
          : []),
      ],
      [
        h.span([], [item.label]),
        h.span([h.AriaHidden(true), h.Class(dragHandleClasses)], ["::"]),
      ]
    );
  };

  const visibleItems = Option.match(maybeDraggedItemId, {
    onNone: () => items,
    onSome: (draggedId) =>
      isDragging ? Array.filter(items, ({ id }) => id !== draggedId) : items,
  });

  const itemElements = Array.map(visibleItems, itemView);
  const isTargetList =
    isDragging &&
    Option.exists(
      maybeDropTarget,
      ({ containerId: targetContainerId }) => targetContainerId === containerId
    );

  const draggedItem = Option.flatMap(maybeDraggedItemId, (draggedId) =>
    Array.findFirst(items, ({ id }) => id === draggedId)
  );

  const dropPlaceholder = h.keyed("div")(
    "drop-placeholder",
    [
      h.AriaHidden(true),
      h.DataAttribute("drop-placeholder", ""),
      h.Class(dragPlaceholderClasses),
    ],
    []
  );

  const targetIndex = Option.match(maybeDropTarget, {
    onNone: () => visibleItems.length,
    onSome: ({ index }) => Math.min(index, visibleItems.length),
  });

  const insertedElement = isPointerDragging
    ? dropPlaceholder
    : Option.match(draggedItem, {
        onNone: () => dropPlaceholder,
        onSome: (item) => itemView(item, targetIndex),
      });

  const renderedItems = isTargetList
    ? pipe(
        itemElements,
        Array.insertAt(targetIndex, insertedElement),
        Option.getOrElse(() => [...itemElements, insertedElement])
      )
    : itemElements;

  const ghost = pipe(
    Ui.DragAndDrop.ghostStyle(model),
    Option.flatMap((style) =>
      Option.map(draggedItem, (item) => ({ item, style }))
    ),
    Option.match({
      onNone: () => h.empty,
      onSome: ({ item, style }) =>
        h.div([h.Style(style), h.Class(dragGhostClasses)], [item.label]),
    })
  );

  return h.div(
    [h.Class(dragRootClasses)],
    [
      h.div(
        [
          ...Ui.DragAndDrop.droppable<ParentMessage>(containerId, label),
          h.Class(dragListClasses),
        ],
        renderedItems
      ),
      ghost,
      h.p([h.Class(dragStatusClasses)], [status]),
    ]
  );
};

import { Match as M, Option, Schema as S } from "effect";
import { Command, Scene, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, expect, test } from "vitest";

import * as DragAndDrop from "./index";

const GotDragAndDropMessage = m("GotDragAndDropMessage", {
  message: DragAndDrop.Message,
});

const Item = S.Struct({
  id: S.String,
  label: S.String,
});

const Model = S.Struct({
  dragAndDrop: DragAndDrop.Model,
  items: S.Array(Item),
  status: S.String,
});

type Model = typeof Model.Type;

const Message = S.Union([GotDragAndDropMessage]);
type Message = typeof Message.Type;

const initialModel: Model = {
  dragAndDrop: DragAndDrop.init({ id: "registry-drag-and-drop" })[0],
  items: [
    { id: "alpha", label: "Alpha" },
    { id: "bravo", label: "Bravo" },
    { id: "charlie", label: "Charlie" },
  ],
  status: "Current order: Alpha, Bravo, Charlie",
};

const reorderItems = (
  items: readonly (typeof Item.Type)[],
  fromIndex: number,
  toIndex: number
): readonly (typeof Item.Type)[] => {
  const item = items[fromIndex];

  if (item === undefined) {
    return items;
  }

  const withoutItem = items.filter((_, index) => index !== fromIndex);
  const boundedTargetIndex = Math.max(0, Math.min(toIndex, withoutItem.length));

  return [
    ...withoutItem.slice(0, boundedTargetIndex),
    item,
    ...withoutItem.slice(boundedTargetIndex),
  ];
};

const orderStatus = (items: readonly (typeof Item.Type)[]): string =>
  `Current order: ${items.map((item) => item.label).join(", ")}`;

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotDragAndDropMessage: ({ message }) => {
        const [dragAndDrop, commands, maybeOutMessage] = DragAndDrop.update(
          model.dragAndDrop,
          message
        );

        const nextItems = Option.match(maybeOutMessage, {
          onNone: () => model.items,
          onSome: M.type<DragAndDrop.OutMessage>().pipe(
            M.tagsExhaustive({
              Reordered: ({ fromIndex, toIndex }) =>
                reorderItems(model.items, fromIndex, toIndex),
              Cancelled: () => model.items,
            })
          ),
        });

        return [
          evo(model, {
            dragAndDrop: () => dragAndDrop,
            items: () => nextItems,
            status: () => orderStatus(nextItems),
          }),
          Command.mapMessages(commands, (message) =>
            GotDragAndDropMessage({ message })
          ),
        ];
      },
    })
  );

const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [],
    [
      DragAndDrop.sortableListView({
        model: model.dragAndDrop,
        containerId: "registry-list",
        items: model.items,
        label: "Registry sortable list",
        status: model.status,
        toParentMessage: (message) => GotDragAndDropMessage({ message }),
      }),
    ]
  );
});

describe("DragAndDrop registry view", () => {
  test("renders sortable items and applies keyboard reorder output", () => {
    const [activatedModel] = update(
      initialModel,
      GotDragAndDropMessage({
        message: DragAndDrop.ActivatedKeyboardDrag({
          itemId: "alpha",
          containerId: "registry-list",
          index: 0,
        }),
      })
    );
    const [movingModel, movingCommands] = update(
      activatedModel,
      GotDragAndDropMessage({
        message: DragAndDrop.PressedArrowKey({ direction: "Down" }),
      })
    );
    const [resolvedModel] = update(
      movingModel,
      GotDragAndDropMessage({
        message: DragAndDrop.ResolvedKeyboardMove({
          targetContainerId: "registry-list",
          targetIndex: 1,
        }),
      })
    );
    const [droppedModel, droppedCommands] = update(
      resolvedModel,
      GotDragAndDropMessage({
        message: DragAndDrop.ConfirmedKeyboardDrop(),
      })
    );

    expect(movingCommands).toHaveLength(1);
    expect(droppedCommands).toHaveLength(1);

    Scene.scene(
      { update, view },
      Scene.with(droppedModel),
      Scene.expect(Scene.text("Alpha")).toExist(),
      Scene.expect(Scene.text("Bravo")).toExist(),
      Scene.expect(Scene.text("Current order: Bravo, Alpha, Charlie")).toExist()
    );
  });
});
